solution.code:
function findIndex(arr, item) {
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === item) return i;
  }
  return -1;
}

console.log(findIndex([3, 6, 9], 9));
console.log(findIndex([3, 6, 9], 4));
